const HMMTO_OPERATION='hotel-match-many-to-one-direct-geo-review-2333-20260914-v1';

function hmmto_best_pair(array $left,array $right): array {
    $best=['score'=>0.0,'shared'=>0,'source'=>'','target'=>''];
    foreach($left as $s)foreach($right as $t){[$score,$shared]=hmfg_similarity((string)$s,(string)$t);if($score>$best['score']||($score===$best['score']&&$shared>$best['shared']))$best=['score'=>round($score,6),'shared'=>$shared,'source'=>(string)$s,'target'=>(string)$t];}
    return $best;
}
function hmmto_review(PDO $db,string $operation=HMMTO_OPERATION): array {
