    $stats=['pending_examined'=>0,'no_unique_identity_examined'=>0,'occupied_lane'=>0,'direct_place_pool'=>0,'ranked'=>0,'safe'=>0,'medium'=>0,'observed'=>0,'no_accepted_bridge'=>0,'weak_bridge'=>0,'star_mismatch'=>0,'numeric_qualifier_conflict'=>0,'meaningful_qualifier_conflict'=>0,'coordinate_conflict'=>0,'weak_identity'=>0,'country_unknown'=>0];$safe=[];$medium=[];$reasons=[];
    foreach($db->query("SELECT * FROM andromeda_hotel_identities WHERE supplier_namespace='andromeda_catalog' AND decision_status='pending' AND local_hotel_id IS NULL ORDER BY external_hotel_id")->fetchAll(PDO::FETCH_ASSOC) as $r){$external=(string)$r['external_hotel_id'];$obs=$latest[$external]??null;$e=fc_evidence($r['evidence_json']??'');$src=$e['source']??[];if(!is_array($src))$src=[];$geo=$e['geography']??[];if(!is_array($geo))$geo=[];$country=(int)($obs['country_id']??0);if(!isset(MBR_CORE8[$country]))$country=(int)($shaCountry[$r['catalog_sha256']]??0);if(!isset(MBR_CORE8[$country])){$stats['country_unknown']++;continue;}$stats['pending_examined']++;
        $sourceNames=hmadb_source_names($e,$obs);if(mbr_ids_for_names($strict,$country,$sourceNames,false)||mbr_ids_for_names($broad,$country,$sourceNames,true))continue;$stats['no_unique_identity_examined']++;
        $sourcePlaces=hmadb_source_places($e,$obs);$placeRank=[];foreach($sourcePlaces as $sp)foreach($catalogPlaces[$country]??[] as $pk=>$meta){$ps=hmdfg_place_similarity($sp,$pk);if($ps>=0.84)$placeRank[]=['source'=>$sp,'target_key'=>$pk,'score'=>round($ps,6),'ids'=>array_map('intval',array_keys($meta['ids']))];}usort($placeRank,static fn($a,$b)=>$b['score']<=>$a['score']);$bp=$placeRank[0]??null;if(!$bp)continue;$secondPlace=$placeRank[1]['score']??0.0;if($secondPlace>0&&$bp['target_key']!==($placeRank[1]['target_key']??'')&&$bp['score']-$secondPlace<0.10)continue;$stats['direct_place_pool']++;
