        $oc=(int)($obsCount[$external]??0);$base=['external_id'=>$external,'country_id'=>$country,'observation_count'=>$oc,'source_names'=>$sourceNames,'source_places'=>$sourcePlaces,'target'=>mbr_row_target($target),'local_name_match'=>$best,'local_second_score'=>round($second,6),'local_margin'=>round($margin,6),'place_evidence'=>['source'=>$bp['source'],'target_key'=>$bp['target_key'],'score'=>$bp['score']],'accepted_bridge'=>$bridgeBest,'guard'=>$guard,'source_category'=>$sourceCat,'target_category'=>$targetCat,'star_mismatch'=>$starMismatch,'evidence'=>'direct_geo_plus_local_fuzzy_plus_existing_andromeda_same_local_bridge'];
        $safeRule=$best['score']>=0.86&&$best['shared']>=2&&$margin>=0.16&&$bridgeBest['score']>=0.92&&(!$starMismatch||($best['score']>=0.95&&$bridgeBest['score']>=0.97));if($safeRule){$base['tier']='safe';$safe[]=$base;$stats['safe']++;if($oc>0)$stats['observed']++;continue;}
        if($best['score']>=0.80&&$best['shared']>=2&&$margin>=0.10&&$bridgeBest['score']>=0.90&&!$starMismatch){$base['tier']='medium';$medium[]=$base;$stats['medium']++;continue;}$stats['weak_identity']++;$reasons['combined_identity_not_strong_enough']=($reasons['combined_identity_not_strong_enough']??0)+1;
    }
    $sort=static fn($a,$b)=>(int)$b['observation_count']<=>(int)$a['observation_count'] ?: $b['local_name_match']['score']<=>$a['local_name_match']['score'] ?: $b['local_margin']<=>$a['local_margin'] ?: strcmp($a['external_id'],$b['external_id']);usort($safe,$sort);usort($medium,$sort);arsort($reasons);
    return ['status'=>'completed','operation_id'=>$operation,'database_writes'=>0,'mapping_writes'=>0,'supplier_calls'=>0,'tourvisor_calls'=>0,'historical_operations_replayed'=>false,'coverage'=>fc_coverage($db),'catalog_scope'=>$scope,'stats'=>$stats,'blocked_reasons'=>$reasons,'safe_count'=>count($safe),'medium_count'=>count($medium),'safe'=>$safe,'medium'=>$medium];
